<?php
declare(strict_types=1);
require_once dirname(__DIR__) . '/youtube/lib.php';
function h(string $v): string { return htmlspecialchars($v,ENT_QUOTES,'UTF-8'); }
function yt(string $url,string $token): array { $d=json_decode(reddottYoutubeHttpGet($url,$token),true); if(!is_array($d)) throw new RuntimeException('Invalid YouTube API response.'); return $d; }
function clean(string $v): string { return trim(preg_replace('/\s+/',' ',$v) ?? ''); }
function slug(string $title): string { $s=strtolower(trim($title)); $s=preg_replace('/[^a-z0-9]+/','-',$s) ?? ''; return trim($s,'-') ?: 'video'; }
$id=trim((string)($_GET['id'] ?? '')); $video=null; $error='';
try {
    if(!preg_match('/^[A-Za-z0-9_-]{6,}$/',$id)) throw new RuntimeException('Invalid video.');
    $connection=reddottYoutubeConnection(); if(!$connection) throw new RuntimeException('YouTube is not connected.');
    $token=reddottYoutubeAccessToken();
    $data=yt('https://www.googleapis.com/youtube/v3/videos?'.http_build_query(['part'=>'snippet,status','id'=>$id],'','&',PHP_QUERY_RFC3986),$token);
    $video=$data['items'][0] ?? null; if(!$video) throw new RuntimeException('Video not found.');
} catch(Throwable $e) { error_log('Reddott Films blog post: '.$e->getMessage()); $error='This article is temporarily unavailable.'; }
if(!$video){http_response_code(404);?><!doctype html><html><head><meta charset="utf-8"><title>Article unavailable — Reddott Films</title></head><body><p><?=h($error)?></p><p><a href="/Reddott-films/blogs/">Back to Reddott Films Blog</a></p></body></html><?php exit;}
$s=$video['snippet'] ?? []; $title=(string)($s['title'] ?? 'Reddott Films video'); $description=clean((string)($s['description'] ?? '')); $published=(string)($s['publishedAt'] ?? ''); $thumb=(string)($s['thumbnails']['maxres']['url'] ?? $s['thumbnails']['high']['url'] ?? $s['thumbnails']['medium']['url'] ?? ''); $indexable=strlen($description)>=240; $canonical='https://smarttoolz.in/Reddott-films/blogs/'.rawurlencode(slug($title)).'/'.rawurlencode($id).'/';
$sentences=preg_split('/(?<=[.!?])\s+/',$description) ?: []; $sentences=array_values(array_filter(array_map('clean',$sentences))); $points=array_slice($sentences,0,4);
$topic='video'; $lower=strtolower($title.' '.$description); if(str_contains($lower,'animation')||str_contains($lower,'fantasy')) $topic='visual storytelling'; elseif(str_contains($lower,'tutorial')||str_contains($lower,'how to')||str_contains($lower,'tool')) $topic='practical learning'; elseif(str_contains($lower,'music')||str_contains($lower,'song')) $topic='music and performance'; elseif(str_contains($lower,'story')||str_contains($lower,'film')) $topic='storytelling';
?>
